{"file_path":"/app/merge_users.py","content":""""
Merge user data from three sources (a > b > c priority) into:
  - /app/merged_users.parquet
  - /app/conflicts.json
"""
import json
from collections import defaultdict

import pandas as pd

# ---------------------------------------------------------------------------
# Priority order (highest first). Source A wins over B wins over C.
# ---------------------------------------------------------------------------
PRIORITY = ["source_a", "source_b", "source_c"]

# ---------------------------------------------------------------------------
# 1. Read and parse all three data sources
# ---------------------------------------------------------------------------

# Source A: JSON (primary)
with open("/data/source_a/users.json", encoding="utf-8") as f:
    source_a_raw = json.load(f)

source_a = []
for rec in source_a_raw:
    source_a.append(
        {
            "user_id": rec["id"],               # id -> user_id
            "name": rec["full_name"],           # full_name -> name
            "email": rec["email"],              # email -> email
            "created_date": rec["registration_date"],  # registration_date -> created_date
            "status": rec.get("status"),        # status (only present in source A)
        }
    )

# Source B: CSV (secondary)
df_b = pd.read_csv("/data/source_b/users.csv")
source_b = []
for _, rec in df_b.iterrows():
    source_b.append(
        {
            "user_id": int(rec["user_id"]),       # user_id
            "name": rec["name"],                  # name -> name
            "email": rec["email_address"],        # email_address -> email
            "created_date": rec["created_at"],    # created_at -> created_date
            "status": None,                      # is_active not part of the specified mappings
        }
    )

# Source C: Parquet (tertiary)
df_c = pd.read_parquet("/data/source_c/users.parquet")
source_c = []
for _, rec in df_c.iterrows():
    source_c.append(
        {
            "user_id": int(rec["userId"]),        # userId -> user_id
            "name": rec["userName"],              # userName -> name
            "email": rec["email"],               # email -> email
            "created_date": rec["joined"],        # joined -> created_date
            "status": None,                      # active not part of the specified mappings
        }
    )

sources = {
    "source_a": source_a,
    "source_b": source_b,
    "source_c": source_c,
}

# Index records by user_id per source
by_source = {name: {rec["user_id"]: rec for rec in records} for name, records in sources.items()}

all_user_ids = set()
for records in by_source.values():
    all_user_ids.update(records.keys())

FIELDS = ["user_id", "name", "email", "created_date", "status"]
DATA_FIELDS = ["name", "email", "created_date", "status"]


def normalize_date(value):
    """Ensure a date value is returned as a YYYY-MM-DD string (or None)."""
    if value is None:
        return None
    if isinstance(value, pd.Timestamp):
        return value.strftime("%Y-%m-%d")
    return pd.to_datetime(str(value)).strftime("%Y-%m-%d")


# ---------------------------------------------------------------------------
# 2. Merge records, resolve conflicts by priority, build conflict report
# ---------------------------------------------------------------------------
merged_records = []
conflicts = []

for uid in sorted(all_user_ids):
    # Start with empty record; fill in priority order so higher priority wins.
    merged = {"user_id": uid, "name": None, "email": None, "created_date": None, "status": None}

    for src in PRIORITY:
        rec = by_source[src].get(uid)
        if rec is None:
            continue
        for field in DATA_FIELDS:
            value = rec.get(field)
            if value is None:
                continue
            # Only fill if not already set (keeps highest-priority value)
            if merged[field] is None:
                merged[field] = value

    # Normalize date to YYYY-MM-DD
    merged["created_date"] = normalize_date(merged["created_date"])

    # Detect conflicts: field present in more than one source with differing values
    for field in DATA_FIELDS:
        present = {}
        for src in PRIORITY:
            rec = by_source[src].get(uid)
            if rec is None:
                continue
            value = rec.get(field)
            if value is None:
                continue
            if field == "created_date":
                value = normalize_date(value)
            present[src] = value

        distinct = set(str(v) for v in present.values())
        if len(distinct) > 1:
            conflicts.append(
                {
                    "user_id": uid,
                    "field": field,
                    "values": {
                        "source_a": present.get("source_a"),
                        "source_b": present.get("source_b"),
                        "source_c": present.get("source_c"),
                    },
                    "selected": merged[field],
                }
            )

    merged_records.append(merged)


# ---------------------------------------------------------------------------
# 3. Write merged output (Parquet) with correct types
# ---------------------------------------------------------------------------
output_df = pd.DataFrame(merged_records, columns=FIELDS)
output_df["user_id"] = output_df["user_id"].astype("int64")

# Keep parquet columns in the requested order; None -> null strings
output_df.to_parquet("/app/merged_users.parquet", index=False, engine="pyarrow")

# ---------------------------------------------------------------------------
# 4. Write conflict report (JSON)
# ---------------------------------------------------------------------------
report = {
    "total_conflicts": len(conflicts),
    "conflicts": conflicts,
}
with open("/app/conflicts.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2, ensure_ascii=False)

print("Merged users:")
print(output_df.to_string(index=False))
print()
print(f"Total conflicts: {len(conflicts)}")
for c in conflicts:
    print(f"  user {c['user_id']} field={c['field']} selected={c['selected']!r}")
"}

